import java.util.*;

class Solution {
    public int change(int amount, int[] coins) {
        Set<List<Integer>> set = new HashSet<>();
        dfs(coins, 0, amount, new ArrayList<>(), set);
        return set.size();
    }

    private void dfs(int[] coins, int start, int rest, List<Integer> path, Set<List<Integer>> set) {
        if (rest == 0) {
            List<Integer> copy = new ArrayList<>(path);
            Collections.sort(copy);
            set.add(copy);
            return;
        }
        if (rest < 0) return;
        for (int i = start; i < coins.length; i++) {
            path.add(coins[i]);
            dfs(coins, i, rest - coins[i], path, set);
            path.remove(path.size() - 1);
        }
    }
}

import java.util.*;

class Solution {
    private int count = 0;

    public int change(int amount, int[] coins) {
        Arrays.sort(coins);
        dfs(coins, 0, amount);
        return count;
    }

    private void dfs(int[] coins, int start, int rest) {
        if (rest == 0) {
            count++;
            return;
        }
        for (int i = start; i < coins.length; i++) {
            if (coins[i] > rest) break;
            dfs(coins, i, rest - coins[i]);
        }
    }
}

class Solution {
    public int change(int amount, int[] coins) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;

        for (int c : coins) {
            for (int j = c; j <= amount; j++) {
                dp[j] += dp[j - c];
            }
        }
        return dp[amount];
    }
}
